from numpy import array

def dicho(t,x,d,f):
    m=(d+f)//2
    if d>f:
        return False
    elif t[m]==x:
        return True
    elif t[m]>x:
        return dicho(t,x,d,m-1)
    else:
        return dicho(t,x,m+1,f)

